SELECT CASE WHEN YEAR(signup_date) < 2024 THEN 'before_2024' WHEN YEAR(signup_date) = 2024 THEN '2024' ELSE 'after_2024' END AS signup_cohort, CASE WHEN credit_limit >= 16500 THEN 'high' WHEN credit_limit >= 7600 THEN 'mid' ELSE 'low' END AS credit_limit_bucket, MIN(age) AS min_age, ROUND(AVG(credit_limit), 2) AS avg_credit_limit, MAX(signup_date) AS latest_signup_date FROM customers WHERE age > 33 GROUP BY 1, 2
